def M(ch, ty, q, o, c, ex, sc=None, st=None, am=None):
    d = {"ch": ch, "ty": ty, "q": q, "o": o, "c": c, "ex": ex}
    if sc: d["sc"] = sc
    if st: d["st"] = st
    if am: d["am"] = am
    return d


def ORD(ch, q, items, c, ex, am=None):
    d = {"ch": ch, "ty": "order", "k": "order", "q": q, "items": items, "c": c, "ex": ex}
    if am: d["am"] = am
    return d


def MAT(ch, q, pairs, c, ex, am=None):
    d = {"ch": ch, "ty": "match", "k": "match", "q": q, "pairs": pairs, "c": c, "ex": ex}
    if am: d["am"] = am
    return d


