for doc, items in NEW.items():
    p = ROOT / "data" / f"{doc}.json"
    D = json.loads(p.read_text("utf-8"))
    have = {(q["q"], q.get("sc")) for q in D["qs"]}
    add = [q for q in items if (q["q"], q.get("sc")) not in have]
    D["qs"].extend(add)
    p.write_text(json.dumps(D, ensure_ascii=False, indent=1), "utf-8")
    print(doc, "thêm", len(add), "câu, tổng", len(D["qs"]))
